1	import { db } from "./db";
2	
3	const SUBNET_PREFIX = "10.20.0.";
4	const IP_START = Number(process.env.NXEON_IP_START ?? 100);
5	const IP_END = Number(process.env.NXEON_IP_END ?? 250);
6	export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
7	export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);
8	
9	export async function allocateIp(): Promise<string> {
10	  const used = new Set(
11	    (await db.server.findMany({ where: { ipAddress: { not: null } }, select: { ipAddress: true } }))
12	      .map((s) => s.ipAddress!)
13	  );
14	  for (let i = IP_START; i <= IP_END; i++) {
15	    const ip = `${SUBNET_PREFIX}${i}`;
16	    if (!used.has(ip)) return ip;
17	  }
18	  throw new Error("IP pool exhausted");
19	}
20	
21	export async function allocateSshPort(): Promise<number> {
22	  const used = new Set(
23	    (await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } }))
24	      .map((s) => s.sshPort!)
25	  );
26	  const usedForwards = new Set(
27	    (await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort)
28	  );
29	  for (let p = SSH_PORT_START; p <= SSH_PORT_END; p++) {
30	    if (!used.has(p) && !usedForwards.has(p)) return p;
31	  }
32	  throw new Error("SSH port pool exhausted");
33	}
34	
35	export function gatewayIp(): string {
36	  return `${SUBNET_PREFIX}1`;
37	}
