3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import {
9	  registrarConfigured,
10	  checkDomains,
11	  registerDomain,
12	  renewDomain,
13	  domainInfo,
14	  listRecords,
15	  addRecord,
16	  deleteRecord,
17	  type RegistrantContact,
18	} from "./registrar";
19	import { domainTerm, domainTermPriceCents } from "./billing-terms";
20	import { debitWallet, InsufficientBalanceError } from "./wallet";
21	
22	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
23	
24	export async function purchaseDomain(prev: any, formData: FormData): Promise<{ error?: string }> {
25	  const user = await requireUser();
26	  if (!registrarConfigured()) {
27	    return { error: "Domain registration is not configured yet (name.com API keys missing)." };
28	  }
29	  const contactSchema = z.object({
30	    firstName: z.string().min(1).max(60),
31	    lastName: z.string().min(1).max(60),
32	    address1: z.string().min(1).max(120),
33	    city: z.string().min(1).max(60),
34	    stateProvince: z.string().min(1).max(60),
35	    postalCode: z.string().min(1).max(20),
36	    country: z.string().length(2),
37	    phone: z.string().regex(/^\+\d{1,3}\.\d{4,14}$/, "Phone format: +1.5551234567"),
38	    email: z.string().email(),
39	  });
40	  const domain = String(formData.get("domain") ?? "").toLowerCase().trim();
41	  if (!DOMAIN_RE.test(domain)) return { error: "Invalid domain name." };
42	  const dTerm = domainTerm(Number(formData.get("years") ?? 1));
43	
44	  const contactParsed = contactSchema.safeParse({
45	    firstName: formData.get("firstName"),
46	    lastName: formData.get("lastName"),
47	    address1: formData.get("address1"),
48	    city: formData.get("city"),
49	    stateProvince: formData.get("stateProvince"),
50	    postalCode: formData.get("postalCode"),
51	    country: String(formData.get("country") ?? "").toUpperCase(),
52	    phone: formData.get("phone"),
53	    email: formData.get("email"),
54	  });
55	  if (!contactParsed.success) {
56	    return { error: contactParsed.error.issues[0]?.message ?? "Invalid registrant contact." };
57	  }
58	
59	  if (await db.domain.findUnique({ where: { name: domain } })) {
60	    return { error: "This domain is already managed by another account." };
61	  }
62	
63	  // Live availability + retail(markup) & cost prices from name.com
64	  let priceCents: number; // retail per year (customer)
65	  let costCents: number; // registrar cost per year (us)
66	  try {
67	    const [check] = await checkDomains([domain]);
68	    if (!check) return { error: "Could not check availability. Try again." };
69	    if (!check.available) return { error: "Domain is not available." };
70	    if (check.premium) return { error: "Premium domains are not supported yet." };
71	    if (check.priceCents === null || check.costCents === null) return { error: "No price available for this TLD." };
72	    priceCents = check.priceCents;
73	    costCents = check.costCents;
74	  } catch (e: any) {
75	    return { error: String(e?.message ?? e).slice(0, 200) };
76	  }
77	
78	  const totalCents = domainTermPriceCents(priceCents, dTerm.years); // customer pays (retail, term-discounted)
79	  const registrarCostCents = costCents * dTerm.years; // we pay name.com the true cost
80	  if (user.balanceCents < totalCents) {
81	    return { error: `Insufficient balance — ${dTerm.label} costs $${(totalCents / 100).toFixed(2)}.` };
82	  }
83	
84	  let record;
85	  try {
86	    record = await db.$transaction(async (tx) => {
87	      await debitWallet(tx, user.id, totalCents);
88	      await tx.walletTransaction.create({
89	        data: { userId: user.id, amountCents: -totalCents, description: `Domain registration: ${domain} (${dTerm.label})` },
90	      });
91	      return tx.domain.create({
92	        data: { name: domain, userId: user.id, priceCents, costCents, termYears: dTerm.years, status: "PENDING", registrar: "name.com" },
93	      });
94	    });
95	  } catch (e) {
96	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
97	    throw e;
98	  }
99	
100	  try {
101	    const { expiresAt } = await registerDomain(domain, dTerm.years, contactParsed.data as RegistrantContact, registrarCostCents);
102	    const info = expiresAt ? { expires: expiresAt } : await domainInfo(domain).catch(() => ({ expires: undefined }));
103	    await db.domain.update({
104	      where: { id: record.id },
105	      data: {
106	        status: "ACTIVE",
107	        registeredAt: new Date(),
108	        expiresAt: info.expires ?? new Date(Date.now() + dTerm.years * 365 * 86400_000),
109	      },
110	    });
111	    await db.auditLog.create({ data: { userId: user.id, action: "domain.register", detail: `${domain} ${dTerm.years}yr` } });
112	    await db.notification.create({
113	      data: { userId: user.id, title: `Domain registered: ${domain}`, href: `/dashboard/domains/${record.id}` },
114	    });
115	  } catch (e: any) {
116	    await db.$transaction([
117	      db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
118	      db.walletTransaction.create({
119	        data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
120	      }),
121	      db.domain.update({
122	        where: { id: record.id },
123	        data: { status: "FAILED", error: String(e?.message ?? e).slice(0, 500) },
124	      }),
125	    ]);
126	    return { error: `Registration failed: ${String(e?.message ?? e).slice(0, 200)} (you were refunded).` };
127	  }
128	  redirect(`/dashboard/domains/${record.id}`);
129	}
