175	// ---------- DNS management ----------
176	
177	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
178	
179	async function ownedDomain(domainId: string) {
180	  const user = await requireUser();
181	  const domain = await db.domain.findUnique({ where: { id: domainId } });
182	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
183	  if (domain.status !== "ACTIVE") throw new Error("Domain is not active");
184	  return { user, domain };
185	}
