41	const dollarsToCents = (d: number | undefined) => (d === undefined ? null : Math.round(d * 100));
42	
43	/** Platform markup added to the registrar cost, as a percentage (admin-tunable via env). */
44	export function domainMarkupPct(): number {
45	  return Number(process.env.DOMAIN_MARKUP_PCT ?? 25);
46	}
47	
48	/** Retail (customer) price for a given registrar cost, markup applied. */
49	export function retailCents(costCents: number | null): number | null {
50	  if (costCents === null) return null;
51	  return Math.round(costCents * (1 + domainMarkupPct() / 100));
52	}
