105	/** Registers for `years` at the given expected price (from checkDomains). */
106	export async function registerDomain(
107	  domain: string,
108	  years: number,
109	  contact: RegistrantContact,
110	  purchaseCents: number
111	): Promise<{ expiresAt?: Date }> {
112	  const c = ncContact(contact);
113	  const json = await nc("POST", "/v4/domains", {
114	    domain: {
115	      domainName: domain,
116	      contacts: { registrant: c, admin: c, tech: c, billing: c },
117	      privacyEnabled: true,
118	    },
119	    purchasePrice: purchaseCents / 100,
120	    years,
121	  });
122	  const exp = json?.domain?.expireDate ?? json?.order?.expireDate;
123	  return { expiresAt: exp ? new Date(exp) : undefined };
124	}
