126	export async function renewDomain(domain: string, years: number, purchaseCents: number): Promise<void> {
127	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}:renew`, {
128	    purchasePrice: purchaseCents / 100,
129	    years,
130	  });
