164	export async function addRecord(
165	  domain: string,
166	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
167	): Promise<void> {
168	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
169	    host: rec.host,
170	    type: rec.type,
171	    answer: rec.answer,
172	    ttl: rec.ttl ?? 300,
173	    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
174	  });
175	}
176	
177	export async function deleteRecord(domain: string, id: number): Promise<void> {
178	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
179	}
