import { db } from "./db";
import type { Prisma } from "@prisma/client";

/**
 * IPAM — private-IP and SSH-forward-port allocation.
 *
 * Node-aware: when a `nodeId` is supplied the pool is taken from that Node's
 * configured range (`subnetPrefix` / `ipStart` / `ipEnd` / `sshPortStart` /
 * `sshPortEnd`). Without a nodeId we fall back to the global env range, which is
 * the single-node behaviour this module has always had.
 *
 * Race safety: `Server.ipAddress` and `Server.sshPort` are UNIQUE columns, so a
 * concurrent double-provision must not hand out the same value twice. When the
 * caller passes the server it is allocating for, the "find free + claim" pair
 * runs inside a single transaction guarded by a Postgres advisory lock, with a
 * retry loop on unique-constraint conflicts. Callers that do not pass a server
 * id get a best-effort pick plus a short-lived in-process reservation (which
 * covers concurrent jobs inside one worker process, the common case).
 */

const ENV_SUBNET_PREFIX = process.env.NXEON_SUBNET_PREFIX ?? "10.20.0.";
const IP_START = Number(process.env.NXEON_IP_START ?? 100);
const IP_END = Number(process.env.NXEON_IP_END ?? 250);
export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);

/** Advisory-lock key that serialises IPAM allocation across processes. */
const IPAM_LOCK_KEY = 728_144_301;
/** How many times we re-pick after losing a unique-constraint race. */
const CLAIM_ATTEMPTS = 8;
/** How long an unclaimed hand-out is remembered in this process. */
const RESERVATION_TTL_MS = 10 * 60_000;

export type IpamRange = {
  nodeId: string | null;
  subnetPrefix: string;
  ipStart: number;
  ipEnd: number;
  sshPortStart: number;
  sshPortEnd: number;
  bridge: string | null;
  natChain: string | null;
};

const GLOBAL_RANGE: IpamRange = {
  nodeId: null,
  subnetPrefix: ENV_SUBNET_PREFIX,
  ipStart: IP_START,
  ipEnd: IP_END,
  sshPortStart: SSH_PORT_START,
  sshPortEnd: SSH_PORT_END,
  bridge: process.env.NXEON_BRIDGE ?? null,
  natChain: process.env.NXEON_NAT_CHAIN ?? null,
};

const num = (v: unknown, fallback: number) =>
  typeof v === "number" && Number.isFinite(v) ? v : fallback;

/**
 * Resolve the pool a node allocates from. Unknown/empty node fields fall back to
 * the global env values so a half-configured Node row can never produce an
 * empty range.
 */
export async function ipamRange(nodeId?: string | null): Promise<IpamRange> {
  if (!nodeId) return { ...GLOBAL_RANGE };
  const node = await db.node.findUnique({
    where: { id: nodeId },
    select: {
      id: true,
      subnetPrefix: true,
      ipStart: true,
      ipEnd: true,
      sshPortStart: true,
      sshPortEnd: true,
      bridge: true,
      natChain: true,
    },
  });
  if (!node) return { ...GLOBAL_RANGE };
  const prefix = node.subnetPrefix?.trim() || GLOBAL_RANGE.subnetPrefix;
  return {
    nodeId: node.id,
    subnetPrefix: prefix.endsWith(".") ? prefix : `${prefix}.`,
    ipStart: num(node.ipStart, GLOBAL_RANGE.ipStart),
    ipEnd: num(node.ipEnd, GLOBAL_RANGE.ipEnd),
    sshPortStart: num(node.sshPortStart, GLOBAL_RANGE.sshPortStart),
    sshPortEnd: num(node.sshPortEnd, GLOBAL_RANGE.sshPortEnd),
    bridge: node.bridge ?? GLOBAL_RANGE.bridge,
    natChain: node.natChain ?? GLOBAL_RANGE.natChain,
  };
}

// ---------- in-process reservations ----------

const reservations = new Map<string, number>();

function isReserved(key: string): boolean {
  const until = reservations.get(key);
  if (until === undefined) return false;
  if (until <= Date.now()) {
    reservations.delete(key);
    return false;
  }
  return true;
}

function reserve(key: string): void {
  if (reservations.size > 5000) {
    const now = Date.now();
    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
  }
  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
}

function isUniqueConflict(e: any): boolean {
  return e?.code === "P2002";
}

type Tx = Prisma.TransactionClient;

/** Serialise allocators. Best-effort: a non-Postgres/permissioned DB just skips it. */
async function lockIpam(tx: Tx): Promise<void> {
  try {
    await tx.$executeRawUnsafe("SELECT pg_advisory_xact_lock($1)", IPAM_LOCK_KEY);
  } catch {
    /* advisory locks unavailable — fall back to the unique-conflict retry loop */
  }
}

// ---------- IP allocation ----------

/**
 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
 * same subnet prefix can conflict — servers on other nodes (different prefix)
 * are naturally excluded. We still read the column globally because
 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
 * happens to hold is what keeps the insert from blowing up.
 */
async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
  const rows = await tx.server.findMany({
    where: { ipAddress: { startsWith: range.subnetPrefix } },
    select: { ipAddress: true },
  });
  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
  for (let i = range.ipStart; i <= range.ipEnd; i++) {
    const ip = `${range.subnetPrefix}${i}`;
    if (used.has(ip)) continue;
    if (isReserved(`ip:${ip}`)) continue;
    return ip;
  }
  throw new Error(
    range.nodeId
      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
      : "IP pool exhausted"
  );
}

/**
 * Allocate a private IP.
 *
 * @param nodeId          allocate from this Node's configured subnet/range.
 * @param claimForServerId when given, the IP is written onto that Server row in
 *                         the same transaction, making the allocation atomic.
 */
export async function allocateIp(
  nodeId?: string | null,
  claimForServerId?: string | null
): Promise<string> {
  const range = await ipamRange(nodeId);

  if (!claimForServerId) {
    // No row to claim against: pick + reserve in-process so concurrent jobs in
    // this worker cannot be handed the same address.
    const ip = await db.$transaction(async (tx) => {
      await lockIpam(tx);
      return pickFreeIp(tx, range);
    });
    reserve(`ip:${ip}`);
    return ip;
  }

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    let ip = "";
    try {
      ip = await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const candidate = await pickFreeIp(tx, range);
        await tx.server.update({
          where: { id: claimForServerId },
          data: { ipAddress: candidate },
        });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) {
        // Someone beat us to it between pick and claim — skip it and retry.
        continue;
      }
      throw e;
    }
    reserve(`ip:${ip}`);
    return ip;
  }
  throw new Error(
    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

// ---------- SSH forward-port allocation ----------

/**
 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
 * taken-set is read globally even though the *range* we scan is per-node.
 * Node-awareness therefore comes from the range: give each node a disjoint
 * sshPortStart/sshPortEnd window and two nodes can never collide.
 */
async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
  const [servers, forwards] = await Promise.all([
    tx.server.findMany({
      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
      select: { sshPort: true },
    }),
    tx.portForward.findMany({
      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
      select: { publicPort: true },
    }),
  ]);
  const used = new Set<number>([
    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
    ...forwards.map((f) => f.publicPort),
  ]);
  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
    if (used.has(p)) continue;
    if (isReserved(`port:${p}`)) continue;
    return p;
  }
  throw new Error(
    range.nodeId
      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
      : "SSH port pool exhausted"
  );
}

/**
 * Allocate an SSH forward port.
 *
 * @param nodeId          allocate from this Node's configured port range.
 * @param claimForServerId when given, the port is written onto that Server row
 *                         in the same transaction, making it atomic.
 */
export async function allocateSshPort(
  nodeId?: string | null,
  claimForServerId?: string | null
): Promise<number> {
  const range = await ipamRange(nodeId);

  if (!claimForServerId) {
    const port = await db.$transaction(async (tx) => {
      await lockIpam(tx);
      return pickFreePort(tx, range);
    });
    reserve(`port:${port}`);
    return port;
  }

  let lastErr: unknown;
  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
    let port = 0;
    try {
      port = await db.$transaction(async (tx) => {
        await lockIpam(tx);
        const candidate = await pickFreePort(tx, range);
        await tx.server.update({
          where: { id: claimForServerId },
          data: { sshPort: candidate },
        });
        return candidate;
      });
    } catch (e) {
      lastErr = e;
      if (isUniqueConflict(e)) continue;
      throw e;
    }
    reserve(`port:${port}`);
    return port;
  }
  throw new Error(
    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
  );
}

// ---------- gateway ----------

/**
 * Gateway for a NAT subnet. Backwards compatible: called with no argument it
 * returns the global gateway exactly as before. Pass a Node's `subnetPrefix`
 * (or use {@link gatewayIpForNode}) for multi-node correctness.
 */
export function gatewayIp(subnetPrefix?: string | null): string {
  const prefix = subnetPrefix?.trim() || ENV_SUBNET_PREFIX;
  return `${prefix.endsWith(".") ? prefix : `${prefix}.`}1`;
}

/** Async node-aware variant of {@link gatewayIp}. */
export async function gatewayIpForNode(nodeId?: string | null): Promise<string> {
  const range = await ipamRange(nodeId);
  return gatewayIp(range.subnetPrefix);
}

