let advisoryLocks: boolean | null = null;

async function lockIpam(tx: Tx): Promise<void> {
  if (advisoryLocks === false) return;
  await tx.$queryRawUnsafe("SELECT pg_advisory_xact_lock($1)", IPAM_LOCK_KEY);
