      }

      if (verdict.state === "not-registered") {
        // Confirmed still available at the registrar — refunding is safe.
        await db.$transaction([
          db.user.update({ where: { id: user.id }, data: { balanceCents: { increment: totalCents } } }),
          db.walletTransaction.create({
            data: { userId: user.id, amountCents: totalCents, description: `Refund: failed registration ${domain}` },
          }),
          db.domain.update({
            where: { id: record.id },
            data: { status: "FAILED", error: reason.slice(0, 500) },
          }),
        ]);
        return { error: `Registration failed: ${reason.slice(0, 200)} (you were refunded).` };
      }

      // Unknown: leave PENDING and charged, flag for manual review. Refunding
      // here risks giving away a domain we actually paid the registrar for.
      await db.domain.update({
        where: { id: record.id },
        data: { status: "PENDING", error: `NEEDS REVIEW — registrar status unconfirmed: ${reason}`.slice(0, 500) },
