      await db.auditLog.create({
        data: { userId: user.id, action: "domain.register.needs_review", detail: `${domain}: ${reason}`.slice(0, 500) },
      });
      await db.notification.create({
        data: {
          userId: user.id,
          title: `Domain ${domain} needs review`,
          body: "We could not confirm the registration with the registrar. Our team is checking it — no duplicate charge will be made.",
          href: `/dashboard/domains/${record.id}`,
        },
      });
      return {
        error:
          `We could not confirm ${domain} with the registrar (${reason.slice(0, 120)}). ` +
          `It is marked for review — do not retry, you will not be charged twice.`,
      };
    }
    redirect(`/dashboard/domains/${record.id}`);
  } finally {
    endSubmit(guardKey);
  }
}

