/** A renewal already landed if the registrar expiry runs ~a month past ours. */
const RENEW_SLACK_MS = 30 * 86400_000;

export async function renewDomainAction(domainId: string): Promise<{ error?: string }> {
  const user = await requireUser();
  const domain = await db.domain.findUnique({ where: { id: domainId } });
  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) return { error: "Not found." };
  if (domain.status === "PENDING") return { error: "This domain's registration is still being confirmed." };
  if (domain.status === "FAILED") return { error: "This domain is not registered." };

  // Short-window duplicate-submit guard (double-click / retry-after-timeout).
  const guardKey = `renew:${domain.userId}:${domain.name}`;
  if (!beginSubmit(guardKey)) {
    return { error: "A renewal for this domain is already in progress." };
  }

  try {
    const dTerm = domainTerm(domain.termYears);
    const renewCents = domainTermPriceCents(domain.priceCents, dTerm.years);
    const owner = await db.user.findUnique({ where: { id: domain.userId } });
    if (!owner || owner.balanceCents < renewCents) return { error: "Insufficient balance." };

    const dbExpiry = domain.expiresAt ?? null;

    // Idempotency: charge and expiry advance together in one transaction below,
    // so if the registrar expiry is already ahead of ours a previous attempt
    // renewed but never got charged/recorded. Adopt that renewal instead of
    // buying a second year.
    let registrarExpiry: Date | undefined;
    try {
      registrarExpiry = (await domainInfo(domain.name)).expires;
    } catch {
      /* non-fatal: fall through to a normal renew */
    }
    const alreadyRenewed =
      !!registrarExpiry && !!dbExpiry && registrarExpiry.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS;

    if (!alreadyRenewed) {
      try {
        await renewDomain(domain.name, dTerm.years, (domain.costCents || domain.priceCents) * dTerm.years);
      } catch (e: any) {
        return { error: `Renewal failed: ${String(e?.message ?? e).slice(0, 200)}` };
      }
      registrarExpiry = await domainInfo(domain.name)
        .then((i) => i.expires)
        .catch(() => undefined);
    }

    const targetExpiry =
      registrarExpiry ?? new Date((dbExpiry ?? new Date()).getTime() + dTerm.years * 365 * 86400_000);

    try {
      const charged = await db.$transaction(async (tx) => {
        // Re-read under the transaction: if a concurrent request already advanced
        // the expiry it also already took the money — do not charge again.
        const fresh = await tx.domain.findUnique({ where: { id: domainId }, select: { expiresAt: true } });
        if (dbExpiry && fresh?.expiresAt && fresh.expiresAt.getTime() > dbExpiry.getTime() + RENEW_SLACK_MS) {
          return false;
        }
        await debitWallet(tx, domain.userId, renewCents);
        await tx.walletTransaction.create({
          data: { userId: domain.userId, amountCents: -renewCents, description: `Domain renewal: ${domain.name} (${dTerm.label})` },
        });
        await tx.domain.update({
          where: { id: domainId },
          data: { expiresAt: targetExpiry, status: "ACTIVE" },
        });
        return true;
      });
      if (!charged) {
        revalidatePath(`/dashboard/domains/${domainId}`);
        return {};
      }
    } catch (e) {
      if (e instanceof InsufficientBalanceError) {
        // The registrar renewal already succeeded — flag the uncollected charge
        // instead of silently swallowing it.
        await db.auditLog
          .create({
            data: {
              userId: domain.userId,
              action: "domain.renew.uncharged",
              detail: `${domain.name}: renewed at registrar but wallet debit of ${renewCents}c failed`,
            },
          })
          .catch(() => {});
        return { error: "Insufficient balance." };
      }
      throw e;
    }
    revalidatePath(`/dashboard/domains/${domainId}`);
    return {};
  } finally {
    endSubmit(guardKey);
  }
}

