let advisoryLocks: boolean | null = null;
// Literal, not a bound parameter: a bound JS number can reach Postgres as
// `numeric` and fail to resolve the pg_advisory_xact_lock(bigint) overload.
const LOCK_SQL = `SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})`;

async function lockIpam(tx: Tx): Promise<void> {
  if (advisoryLocks === false) return;
  await tx.$queryRawUnsafe(LOCK_SQL);
}

async function probeAdvisoryLocks(): Promise<void> {
  if (advisoryLocks !== null) return;
  try {
    // Take and immediately release it (xact locks drop at commit). Done once,
    // outside the hot path, because a failing statement inside an open
    // transaction would abort that transaction.
    await db.$transaction(async (tx) => {
      await tx.$queryRawUnsafe(LOCK_SQL);
    });
    advisoryLocks = true;
  } catch {
    // Not Postgres, or the role lacks permission: the unique-conflict retry
    // loop plus in-process reservations remain as the safety net.
    advisoryLocks = false;
  }
}

